head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getCellChecked]<br/>Row 인덱스와 Column 정보를 사용하여 특정 Body Cell 의 체크 상태를 반환합니다. inputType 이 'checkbox','radio','custom' 인 경우에만 동작합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 체크 상태를 조회할 Cell 의 Row 인덱스를 설정해야 합니다. (0 부터 시작, 표시 Row 기준)",
        "columnInfo(필수) 파라미터로 체크 상태를 조회할 Cell 의 Column 인덱스 또는 ID 를 설정해야 합니다.",
        "inputType 이 'checkbox','radio','custom' 인 경우에만 동작해야 합니다.",
        "Cell 데이터값이 trueValue 와 일치하면 true, 일치하지 않으면 false 를 반환해야 합니다.",
        "Cell 을 찾지 못하거나 inputType 이 'checkbox','radio' 가 아니면 false 를 반환해야 합니다.",
        "메소드 실행 중 예외가 발생하면 undefined 를 반환해야 합니다.",
        "inputType='custom' 이면 실제 Cell 의 inputType 이 'checkbox','radio' 인 Cell 만 처리해야 합니다.",
        "DataList 에 저장된 값으로 체크 상태를 판단해야 합니다. (편집 중인 Cell 값이 아님)",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 inputType 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="0:name(text) / 1:chkBin(checkbox·binary) / 2:chkBool(checkbox·boolean) / 3:rdo(radio·binary) / 4:cst(custom, Row0=checkbox·Row1=text·Row2=radio·Row3=checkbox) / 5:txt(text)"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    // - chkBin  : checkbox(binary) 원본값 1/0
    // - chkBool : checkbox(boolean) 원본값 true/false
    // - rdo     : radio 원본값 Y/N
    // - cst     : custom 컬럼 원본값 (checkbox/radio 셀은 trueValue 값, text 셀은 표시 문자열)
    // - txt     : text 컬럼 (checkbox/radio 아님 → 항상 false)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chkBin" name="chkBin" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chkBool" name="chkBool" dataType="text"></w2:column>';
    strDlt += '<w2:column id="rdo" name="rdo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cst" name="cst" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txt" name="txt" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // Row0/Row2 = 체크(trueValue "1"), Row1/Row3 = 미체크(falseValue "0")
    // cst : Row0=checkbox(1=체크), Row1=text, Row2=radio(1=체크), Row3=checkbox(0=미체크)
    let jsonData = [
        { "name": "John", "chkBin": "1", "chkBool": "true",  "rdo": "1", "cst": "1",    "txt": "메모0" },
        { "name": "Jane", "chkBin": "0", "chkBool": "false", "rdo": "0", "cst": "text", "txt": "메모1" },
        { "name": "Mike", "chkBin": "1", "chkBool": "true",  "rdo": "1", "cst": "1",    "txt": "메모2" },
        { "name": "Amy",  "chkBin": "0", "chkBool": "false", "rdo": "0", "cst": "0",    "txt": "메모3" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    // setCellInputTypeCustom=true → custom 컬럼에 setCellInputType 으로 행별 inputType 부여 가능
    let properties = {
        dataList: "data:dlt_bind",
        setCellInputTypeCustom: "true",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 6컬럼)
    // 마지막 txt 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:720px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getCellChecked 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="chkBin(binary)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="chkBool(boolean)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="hcol4" value="rdo(radio)"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol5" value="cst(custom)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol6" value="txt(text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : name (text)
    strTarget += '<w2:column width="100" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 1 : chkBin (checkbox, valueType=binary) - trueValue="1" falseValue="0"
    strTarget += '<w2:column width="120" style="" inputType="checkbox" valueType="binary" id="chkBin" dataList="chkBin" trueValue="1" falseValue="0"></w2:column>';
    // index 2 : chkBool (checkbox, valueType=boolean) - trueValue="true" falseValue="false"
    strTarget += '<w2:column width="120" style="" inputType="checkbox" valueType="boolean" id="chkBool" dataList="chkBool" trueValue="true" falseValue="false"></w2:column>';
    // index 3 : rdo (radio, valueType=binary) - trueValue="1" falseValue="0"
    strTarget += '<w2:column width="90" style="" inputType="radio" valueType="binary" id="rdo" dataList="rdo" trueValue="1" falseValue="0"></w2:column>';
    // index 4 : cst (custom) - 행별 inputType 혼합 (setCellInputType 으로 지정)
    strTarget += '<w2:column width="110" style="" inputType="custom" id="cst" dataList="cst" trueValue="1" falseValue="0"></w2:column>';
    // index 5 : txt (text) - checkbox/radio 아님 → 항상 false, width="*"
    strTarget += '<w2:column width="*" style="" inputType="text" id="txt" dataList="txt"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // cst(custom) 컬럼 행별 inputType 부여 (@spec1)
    //  Row0 = checkbox(1=체크), Row1 = text(체크 대상 아님), Row2 = radio(1=체크), Row3 = checkbox(0=미체크)
    target1.setCellInputType(0, "cst", { inputType: "checkbox" });
    target1.setCellInputType(1, "cst", { inputType: "text" });
    target1.setCellInputType(2, "cst", { inputType: "radio" });
    target1.setCellInputType(3, "cst", { inputType: "checkbox" });
}



// getCellChecked 확인 : par_rowIndex / par_columnInfo(컬럼 인덱스) 로 호출 → 체크 상태(true/false) 반환
//  - chkBin(인덱스1)  : Row0/Row2 데이터 "1"=trueValue → true, Row1/Row3 "0" → false
//  - chkBool(인덱스2) : Row0/Row2 "true"=trueValue → true, Row1/Row3 "false" → false
//  - rdo(인덱스3)     : Row0/Row2 "1"=trueValue → true, Row1/Row3 "0" → false
//  - cst(인덱스4)     : custom → checkbox/radio 셀(Row0,Row2,Row3)만 처리, text 셀(Row1)은 false
//  - txt(인덱스5)     : text 컬럼 → 항상 false
scwin.btn_getCellChecked_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    // columnInfo 는 컬럼 인덱스(Number) 로 전달
    let colIndex = Number(par_columnInfo.getValue());
    let rtn = target1.getCellChecked(rowIndex, colIndex);
    if (typeof rtn === 'undefined') {
        rtn = 'undefined';
    }
    wf_body_bottom.getObj("scwin").setReturnValue("getCellChecked(" + rowIndex + ", " + colIndex + ") : " + rtn);
}



// 유효하지 않은 파라미터 : 범위를 벗어난 rowIndex / colIndex → undefined 반환 (예외 발생)
scwin.btn_getInvalid_onclick = function () {
    let rtn = target1.getCellChecked(99, 99);
    if (typeof rtn === 'undefined') {
        rtn = 'undefined';
    }
    wf_body_bottom.getObj("scwin").setReturnValue("[유효하지 않은 파라미터] getCellChecked(99, 99) : " + rtn);
}
